<template><section class="business-page"><header class="page-header"><div><h1>{{ title }}</h1><p>{{ subtitle }}</p></div><el-button v-if="mode!=='attribute'&&canManage" type="primary" @click="openCreate">新增</el-button></header><el-table :data="rows" border v-loading="loading"><el-table-column v-if="mode==='category'" prop="level" label="层级" width="80"/><el-table-column prop="code" label="编码"/><el-table-column prop="name" label="中文名称"/><el-table-column v-if="mode==='attribute'" label="SKU 属性（按编码顺序）" min-width="300"><template #default="{row}">{{ (row.spec_dimensions||[]).map(x=>`${x.name}(${x.code})`).join('、')||'未设置' }}</template></el-table-column><el-table-column label="状态" width="90"><template #default="{row}">{{row.is_active?'启用':'停用'}}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button v-if="canManage" link type="primary" @click="edit(row)">{{mode==='attribute'?'设置属性':'编辑'}}</el-button></template></el-table-column></el-table><el-dialog v-model="visible" :title="dialogTitle" width="560px"><el-form label-position="top"><template v-if="mode==='category'"><el-form-item label="层级"><el-select v-model="form.level"><el-option v-for="n in 3" :key="n" :label="`L${n}`" :value="n"/></el-select></el-form-item><el-form-item v-if="form.level>1" label="上级分类"><el-select v-model="form.parent"><el-option v-for="x in parents" :key="x.id" :label="`L${x.level} ${x.code} ${x.name}`" :value="x.id"/></el-select></el-form-item></template><el-form-item v-if="mode!=='attribute'" label="编码"><el-input v-model="form.code" :disabled="!!form.id"/></el-form-item><el-form-item v-if="mode!=='attribute'" label="中文名称"><el-input v-model="form.name"/></el-form-item><el-form-item v-if="mode==='attribute'" label="属性（每行：英文编码,中文名称）"><el-input v-model="form.dimensions" type="textarea" :rows="8" placeholder="width,宽度&#10;length,长度"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></section></template>
<script setup>import{computed,onMounted,reactive,ref,watch}from'vue';import{ElMessage}from'element-plus';import{useAuthStore}from'../../stores/auth';import{createProductCategory,createProductColor,fetchProductCategories,fetchProductColors,updateProductAttributes,updateProductCategory,updateProductColor}from'../../api/products';import{collectionRows}from'../../utils/businessResponse';const props=defineProps({mode:{type:String,required:true}}),auth=useAuthStore(),rows=ref([]),loading=ref(false),visible=ref(false),form=reactive({});const cfg=computed(()=>({category:['分类设置','维护三级商品分类与编码','products.category.manage'],color:['颜色设置','维护 SKU 颜色编码字典','products.color.manage'],attribute:['属性设置','为末级分类单独维护 SKU 属性及编码顺序','products.attribute.manage']}[props.mode]));const title=computed(()=>cfg.value[0]),subtitle=computed(()=>cfg.value[1]),canManage=computed(()=>auth.hasPermission(cfg.value[2])),dialogTitle=computed(()=>props.mode==='attribute'?'设置 SKU 属性':`${form.id?'编辑':'新增'}${title.value.replace('设置','')}`),parents=computed(()=>rows.value.filter(x=>x.level===form.level-1));async function load(){loading.value=true;const r=props.mode==='color'?await fetchProductColors():await fetchProductCategories(props.mode==='attribute'?{level:3}:{});rows.value=r.success?collectionRows(r.data):[];loading.value=false}function openCreate(){Object.assign(form,{id:null,level:1,parent:null,code:'',name:''});visible.value=true}function edit(row){Object.assign(form,row,{dimensions:(row.spec_dimensions||[]).map(x=>`${x.code},${x.name}`).join('\n')});visible.value=true}async function save(){let r;if(props.mode==='attribute'){const dims=form.dimensions.split('\n').map(x=>x.trim()).filter(Boolean).map(x=>{const[code,...name]=x.split(',');return{code:code.trim(),name:name.join(',').trim()}});r=await updateProductAttributes(form.id,dims)}else if(props.mode==='color')r=form.id?await updateProductColor(form.id,{name:form.name,is_active:form.is_active}):await createProductColor({code:form.code,name:form.name});else r=form.id?await updateProductCategory(form.id,{name:form.name,is_active:form.is_active}):await createProductCategory({level:form.level,parent:form.parent,code:form.code,name:form.name});if(!r.success)return ElMessage.error(r.message||'保存失败');ElMessage.success('保存成功');visible.value=false;load()}watch(()=>props.mode,load);onMounted(load)</script>
